import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { vendorService } from '../../services/vendorService';
import LoadingSpinner from '../common/LoadingSpinner';
import Modal from '../common/Modal';
import { getErrorMessage, getStatusText, getStatusColor, formatDateTime } from '../../utils/helpers';

const ApplicationStatus = () => {
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [selectedApp, setSelectedApp] = useState(null);
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    loadApplications();
  }, []);

  const loadApplications = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await vendorService.getApplications();
      setApplications(response.data);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitApplication = async (applicationId) => {
    setSubmitting(true);
    setMessage('');
    setError('');

    try {
      await vendorService.submitApplication(applicationId);
      setMessage('Application submitted successfully!');
      setShowModal(false);
      loadApplications(); // Refresh the list
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setSubmitting(false);
    }
  };

  const openSubmitModal = (application) => {
    setSelectedApp(application);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setSelectedApp(null);
    setError('');
  };

  const getStatusDescription = (status) => {
    const descriptions = {
      DRAFT: 'Your application is saved as draft. You can submit it for review.',
      SUBMITTED: 'Your application has been submitted and is waiting for review.',
      UNDER_REVIEW: 'Your application is currently being reviewed by our team.',
      APPROVED: 'Congratulations! Your application has been approved.',
      REJECTED: 'Your application has been rejected. Please check the comments for details.',
      INSPECTION_SCHEDULED: 'An inspection has been scheduled for your food truck.',
      INSPECTION_COMPLETED: 'The inspection has been completed. Awaiting final decision.',
      LICENSED: 'Your food truck license has been issued. You can now operate!'
    };
    return descriptions[status] || 'Status update pending.';
  };

  const canSubmit = (application) => {
    return application.status === 'DRAFT';
  };

  const canCreateNew = () => {
    // Allow creating new application if no draft exists
    return !applications.some(app => app.status === 'DRAFT');
  };

  if (loading) {
    return <LoadingSpinner message="Loading your applications..." />;
  }

  return (
    <div className="application-status-page">
      <div className="container">
        <div className="page-header">
          <h1>Application Status</h1>
          <p>Track the progress of your license applications</p>
        </div>

        {message && <div className="success-message">{message}</div>}
        {error && !showModal && <div className="error-message">{error}</div>}

        <div className="status-actions">
          {canCreateNew() ? (
            <Link to="/application" className="btn btn-primary">
              Create New Application
            </Link>
          ) : (
            <span className="info-text">You have a draft application. Submit it before creating a new one.</span>
          )}
        </div>

        {applications.length > 0 ? (
          <div className="applications-container">
            {applications.map((application) => (
              <div key={application.id} className="application-card">
                <div className="application-header">
                  <div className="application-id">
                    <h3>Application #{application.id}</h3>
                  </div>
                  <div className={`status-badge ${getStatusColor(application.status)}`}>
                    {getStatusText(application.status)}
                  </div>
                </div>

                <div className="application-details">
                  <div className="detail-row">
                    <span className="label">Created:</span>
                    <span className="value">{formatDateTime(application.createdAt)}</span>
                  </div>

                  {application.submittedAt && (
                    <div className="detail-row">
                      <span className="label">Submitted:</span>
                      <span className="value">{formatDateTime(application.submittedAt)}</span>
                    </div>
                  )}

                  {application.reviewedAt && (
                    <div className="detail-row">
                      <span className="label">Reviewed:</span>
                      <span className="value">{formatDateTime(application.reviewedAt)}</span>
                    </div>
                  )}

                  {application.inspectedAt && (
                    <div className="detail-row">
                      <span className="label">Inspected:</span>
                      <span className="value">{formatDateTime(application.inspectedAt)}</span>
                    </div>
                  )}
                </div>

                <div className="status-description">
                  <p>{getStatusDescription(application.status)}</p>
                </div>

                {application.comments && (
                  <div className="application-comments">
                    <h4>Comments:</h4>
                    <p>{application.comments}</p>
                  </div>
                )}

                {application.assignedReviewer && (
                  <div className="assigned-info">
                    <span className="label">Assigned Reviewer:</span>
                    <span className="value">{application.assignedReviewer.username}</span>
                  </div>
                )}

                {application.assignedInspector && (
                  <div className="assigned-info">
                    <span className="label">Assigned Inspector:</span>
                    <span className="value">{application.assignedInspector.username}</span>
                  </div>
                )}

                <div className="application-actions">
                  {canSubmit(application) && (
                    <button
                      onClick={() => openSubmitModal(application)}
                      className="btn btn-primary"
                      disabled={submitting}
                    >
                      Submit Application
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="no-applications">
            <div className="empty-state">
              <h3>No Applications Yet</h3>
              <p>You haven't created any license applications yet.</p>
              <Link to="/application" className="btn btn-primary">
                Create Your First Application
              </Link>
            </div>
          </div>
        )}

        {/* Submit Confirmation Modal */}
        <Modal
          isOpen={showModal}
          onClose={closeModal}
          title="Submit Application"
          size="medium"
        >
          {selectedApp && (
            <div className="submit-modal">
              {error && <div className="error-message">{error}</div>}
              
              <p>Are you sure you want to submit Application #{selectedApp.id}?</p>
              <p className="warning-text">
                Once submitted, you won't be able to make changes to this application.
              </p>

              <div className="modal-actions">
                <button 
                  onClick={closeModal} 
                  className="btn btn-outline"
                  disabled={submitting}
                >
                  Cancel
                </button>
                <button 
                  onClick={() => handleSubmitApplication(selectedApp.id)}
                  className="btn btn-primary"
                  disabled={submitting}
                >
                  {submitting ? 'Submitting...' : 'Confirm Submit'}
                </button>
              </div>

              {submitting && <LoadingSpinner message="Submitting your application..." />}
            </div>
          )}
        </Modal>
      </div>
    </div>
  );
};

export default ApplicationStatus;
